window.SAQ_PAPER_QUESTIONS["2019-1-schhs-metro-north"]=[{"number":1,"title":"","stemText":"(18 marks) An 81-year-old man is brought in by ambulance to your tertiary emergency department with a reduced level\n• f consciousness. Neighbours broke into his home after not seeing him for 2 days to find him in bed,\nunresponsive and incontinent of urine. On assessment his airway is patent, respiratory rate is 17 breaths/minute, saturations are 95% on 2L oxygen, heart rate is 93 bpm, BP is 117/85mmHg and temperature is 36.4 degrees Celsius. Neurological assessment reveals a Glasgow Coma Scale of 6 (E1 V2 M3); pupils are 2mm and sluggish, there is left-sided hemiplegia.\nHis bedside glucose is 7.1\nA non-contrast CT brain is performed. Two slices from CT are shown in the Props Booklet (Figures 1a and 1b):","parts":[{"id":"a","label":"Part A","prompt":"List two positive and two negative findings on this single slice CT scan (4 marks)"},{"id":"b","label":"Part B","prompt":"Provide a unifying diagnosis (1 mark) You learn that he has no significant past medical history and takes no regular medications. He lives alone and up to now has been independent in his activities of daily living. The patient’s brother and sister arrive and would like to know what happened to him and what his prognosis is."},{"id":"c","label":"Part C","prompt":"List important information that should be included in your discussion with his relatives (5 marks) Following your discussion, a decision is made to palliate the patient who seems to be comfortable and shows no signs of distress. He is accepted for admission under the palliative care team who ask you to complete his medication chart, including dose he may require on a ‘as needed’ (p.r.n.) basis."},{"id":"d","label":"Part D","prompt":"List the ‘as needed’ (p.r.n.) medications that should be charted for this patient with a indication for each and a dosing regimen. (8 marks) Indication Medication Dosing regime"}],"propPages":["asset:img641e76fc8901a02260","asset:img14b863b339ab127ec8"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hyperdensity midbrain and pons consistent with acute bleed</div><div class=\"answer-line\">dilatation of lateral horns – likely related to mass effect from bleed, probably</div><div class=\"answer-line\">Hydrocephalus</div><div class=\"answer-line\">No <strong>tonsillar herniation </strong></div><div class=\"answer-line\">No intraventricular blood</div><div class=\"answer-line\">No signs of trauma (soft tissue swelling or bony fracture) on non-dedicated limited views</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">acute/subacute <strong>intracranial haemorrhage</strong> –spontaneous.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Diagnosis: acute brainstem bleed/ bleeding on the brain</div><div class=\"answer-line\">Prognosis: most likely to be a life-ending event, if survived will have severe neurological</div><div class=\"answer-line\">deficits.</div><div class=\"answer-line\">Patient’s wishes: any previously expressed wishes. Values independence</div><div class=\"answer-line\">Plan: Ceilings/goals of care discussion</div><div class=\"answer-line\">Expected course of illness/ disposition</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pain/dyspnoea</td><td>Morphine 2.5-5mg sc 30minutely</td></tr><tr><td>(fentanyl)</td><td>(25-50mcg 30minutely)</td></tr><tr><td>anxiety/agitation</td><td>Midazolam 2.5- 5mg sc hrly</td></tr><tr><td>(haloperidol)</td><td>(0.5-1mg sc 3hrly)</td></tr><tr><td>nausea/vomiting</td><td>Haloperidol 0.5-1mg sc 3hrly</td></tr><tr><td>(ondansetron)</td><td>(4mg sl 8hrly/ )</td></tr><tr><td>(metoclopramide)</td><td>(10mg sc 4hrly)</td></tr><tr><td>Respiratory</td><td>Hyoscine butylbromide 200-400mcg sc 2hrly</td></tr><tr><td>secretions</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"(18 marks) An acutely aggressive 24-year-old man is brought into your emergency department by ambulance and police after being found alone on a bridge.","parts":[{"id":"a","label":"Part A","prompt":". Give a stepwise approach to managing this aggressive patient with specific examples. (5 marks)"},{"id":"b","label":"Part B","prompt":". Complete the following table for the components of a mental state examination. For each component give an example of what specifically should be assessed (8 marks) Component What to assess"},{"id":"c","label":"Part C","prompt":". List 10 risk factors that are associated with a high risk for suicide (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">verbal de-escalation</div><div class=\"answer-line\">show of force</div><div class=\"answer-line\">offer oral chemical restraint – 5-10mg PO diazepam, 5-10mg PO olanzapine</div><div class=\"answer-line\">physical restraint</div><div class=\"answer-line\">parenteral restraint – 10mg IM droperidol, 10mg IM or 2.5-5mg IV midazolam, 10mg IM</div><div class=\"answer-line\">olanzapine</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Appearance + behaviour:</td><td>physical appearance (cleanliness, grroming), manner of</td></tr><tr><td>relating to clinicans/family, activity level (slow/agitated)</td><td></td></tr><tr><td>Speech:</td><td>spontaneous/not, fuency, rate, volume, tone</td></tr><tr><td>Mood:</td><td>Predominant mood over last weeks, 0-10 scale</td></tr><tr><td>Affect:</td><td>observed emotional state: type, range, reactivity,</td></tr><tr><td>appropriateness</td><td></td></tr><tr><td>Thoughts:</td><td>stream, form, content</td></tr><tr><td>Perception:</td><td>altered bodily experiences, passivity phenomenon,</td></tr><tr><td>hallucinations</td><td></td></tr><tr><td>Cognition:</td><td>LOC, orientation, attention, memory, ability</td></tr><tr><td>Insight and judgement</td><td>Insight into perception disrders, (problem-solving)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Male gender</div><div class=\"answer-line\">Marital status – separated, divorced, widowed</div><div class=\"answer-line\">Unemployed/retired</div><div class=\"answer-line\">Chronic illness/pain</div><div class=\"answer-line\">Psychiatric diagnosis – depression, bipolar, schizophrenia, substance abuse</div><div class=\"answer-line\">Social background – socially isolated, indigenous or refugee background</div><div class=\"answer-line\">Suicidal ideation</div><div class=\"answer-line\">Multiple previous attempts</div><div class=\"answer-line\">Access to violent, lethal method</div><div class=\"answer-line\">Clear plan</div><div class=\"answer-line\">Act performed in isolation/precautions taken to avoid discovery</div><div class=\"answer-line\">Final acts – wills, insurance, giving away property</div><div class=\"answer-line\">Unwilling to seek help</div><div class=\"answer-line\">Precipitant - stressor</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"Your registrar asks for your advice about the clinical decision rules for imaging in paediatric head injury management. They have just seen an 18-month old girl who has been brought in by her mother after she fell off a couch and hit her head on the coffee table one hour ago. The mother is concerned because she seems quieter than normal and has vomited once on the way in to hospital. On assessment, the child is alert, and is happily playing with her Mum’s phone. She has a small frontal haematoma, equal reactive pupils and no focal neurology.","parts":[{"id":"a","label":"Part A","prompt":". Detail the main differences between research evidence behind the PECARN , CHALICE and CATCH clinical decision rules. (4 marks) After taking a detailed history and completing your assessment, you decide that the child does NOT require a CT brain."},{"id":"b","label":"Part B","prompt":". The mother is asking for a CT scan of her daughter’s head as she is worried about concussion. List the important facts that should be mentioned in this conversation (4 marks)"},{"id":"c","label":"Part C","prompt":"State your management plan for this patient (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">PECARN prospectively validated</div><div class=\"answer-line\">CATCH , CHALICE uses ‘rule in ‘ criteria (decides who NEEDS CT)</div><div class=\"answer-line\">PECARN uses ‘rule out’ criteria (decides who NOT to CT)</div><div class=\"answer-line\">PECARN has highest point sensitivity</div><div class=\"answer-line\">CATCH , CHALICE more specific but less sensitive</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Not required as per best evidence</div><div class=\"answer-line\">CTB performed to diagnose injury that requires neurosurgical intervention</div><div class=\"answer-line\">Concussion managed conservatively</div><div class=\"answer-line\">Risk of radiation: lifetime cancer mortality risk from a single head CT is about</div><div class=\"answer-line\">1 in 1,500 in a 1 year old; 1 in 10,000 in a 10 year old</div><div class=\"answer-line\">Risk related to sedation if required</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Observation period- ED SSU with hourly neuro obs</div><div class=\"answer-line\">If any deterioration- CT</div><div class=\"answer-line\">If remains well, discharge</div><div class=\"answer-line\">Discharge advice on ongoing management</div><div class=\"answer-line\">Return to ED advice</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 74year-old man is brought in by ambulance to your regional emergency department after a falling down three steps onto his right hand. It is a closed and isolated injury. His right wrist x-rays are shown in the Props\nBooklet (Figures 2a and 2b).","parts":[{"id":"a","label":"Part A","prompt":"List the abnormalities seen (3 marks)."},{"id":"b","label":"Part B","prompt":"List two short-term and two long-term potential complications of this injury (4 marks). Short-term complications Long-term complications"},{"id":"c","label":"Part C","prompt":"List your management priorities (3 marks)"},{"id":"d","label":"Part D","prompt":"What other factors need to be considered in this patient prior to discharge?( 2marks)"}],"propPages":["asset:img5f97ebe10436cecae9","asset:img3915be4c61a34effd0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Peri-lunate dislocation: radio-lunate articulation maintained with carpus dislocated posteriorly.</div><div class=\"answer-line\">Radial styloid #</div><div class=\"answer-line\">Ulnar styloid #</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Severe pain</td><td>Chronic pain</td></tr><tr><td colspan=\"2\">Early arthritis</td></tr><tr><td>Neurovascular compromise – median nerve</td><td>Chronic carpal instability (DISI and VISI)</td></tr><tr><td>injury</td><td>Decreased grip strength and stiffness common</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia (likely to require intravenous opiates such as morphine 2.5-5mg IV aliquots)</div><div class=\"answer-line\">Urgent consultation with orthopaedics/hand for urgent attempt at closed reduction</div><div class=\"answer-line\">(i.e. in ED under procedural sedation or with Bier’s block).</div><div class=\"answer-line\">Orthopaedic follow-up – admission for ORIF.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Likely dominant hand- will need assistance</div><div class=\"answer-line\">Reason for fall</div><div class=\"answer-line\">Need for aged care/allied heath assessment</div><div class=\"answer-line\">Safety for discharge</div><div class=\"answer-line\">Discharge advice/f/up</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 3-year-old boy is brought in by his mother after ingesting an unknown quantity of liquid paracetamol. He had been playing quietly in his room for 10 minutes and was found with the empty bottle that previously was around three quarters full. The time of ingestion was 30 minutes prior to presentation. The entire 200ml bottle of paracetamol contains 10g of paracetamol. The child weighs 14kg.","parts":[{"id":"a","label":"Part A","prompt":". What is your approach to decontamination of this child? (1 mark) As part of your risk assessment you calculate the possible dose of paracetamol ingested."},{"id":"b","label":"Part B","prompt":". What is the threshold ingested dose of paracetamol (in mg/kg) at and above which a serum paracetamol level should be measured? (1 mark) You decide this child DOES require a paracetamol level to be checked."},{"id":"c","label":"Part C","prompt":". How long after ingestion will you check a paracetamol level in this child? (1 mark) The child’s parents are appropriately concerned for their child and want to ensure there is no further risk to the child from accidental ingestions in the home. They ask you more questions about dangerous ingestions in children."},{"id":"d","label":"Part D","prompt":". List 4 medications that may be life threatening if a small child ingested one or two pills. (4 marks) After completing the appropriate testing, you have decided this child needs treatment with N-acetylcysteine. Soon after commencing the appropriate first infusion, the child develops wide spread erythematous flushing and wheeze."},{"id":"e","label":"Part E","prompt":". List 5 steps in your immediate management. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Decontamnation is not indicated in well children &lt;6yo with isolated liquid paracetamol</div><div class=\"answer-line\">ingestions as they have rapid absorption.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">200mg/kg of liquid paracetamol</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">2 hours for a well child &lt;6yo with an isolated accidental liquid paracetamol ingestion</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Sodium channel blockers</div><div class=\"answer-line\">diphenoxylate/ atropine</div><div class=\"answer-line\">Calcium channel blockers</div><div class=\"answer-line\">Theophylline SR</div><div class=\"answer-line\">Sulfonylureas</div><div class=\"answer-line\">Recreational sympathomimetic drugs</div><div class=\"answer-line\">Opiates</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Stop the N-acetylcysteine infusion<strong> </strong></div><div class=\"answer-line\">Give bronchodilator: salbutamol 2.5mg nebulized with O2 6L/min via nebulized mask –</div><div class=\"answer-line\">aim O2 sats &gt;94%<strong> </strong></div><div class=\"answer-line\">Give antihistamine : certirizine 2.5mg – 5mg PO<strong> </strong></div><div class=\"answer-line\">Give prednisone: 1mg/kg PO<strong> </strong></div><div class=\"answer-line\">Once wheeze and rash has settled, restart acetylcysteine infusion at SLOWER rate and</div><div class=\"answer-line\">carefully monitor.<strong> </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 23-year-old male is brought to your urban district Emergency Department. He has been unwell for the last two weeks with fever and a cough, which began after working in flood clean up on the North Queensland coast. He has a background of well controlled asthma and has no allergies. A senior registrar has commenced therapy but has called for your assistance. The patient is currently receiving a nebuliser. He is alert but intermittently combative with the nebuliser. His initial vital signs are:\nPulse 130 bpm\n\nBP 100/65 mmHg\nCool peripheries\n\nSaO2 73% on 6L oxygen via Nebuliser Mask\n\nTemp 38.5\n\nBSL 6.9\nAuscultation reveals bilateral crackles and minimal wheeze. A CXR is performed and is shown in the Props\nBooklet (Figure 3)","parts":[{"id":"a","label":"Part A","prompt":". List and justify four (4) potential anti-infective choices based on potential microbiology for this patient. (4 marks) Despite initial therapy, the patient fails to improve. You are concerned he has developed Acute Respiratory Distress Syndrome (ARDS)."},{"id":"b","label":"Part B","prompt":". List six (6) non-respiratory causes of ARDS in any patient. (3 marks)"},{"id":"c","label":"Part C","prompt":". State your escalating approach to oxygenation in this patient. (5 marks)"}],"propPages":["asset:imgb9ff3518ce1d275391"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ceftriaxone 1g IV once daily: Coverage for typical severe community acquired pneumonia,</div><div class=\"answer-line\">principally pneumococcus.</div><div class=\"answer-line\">Azithromycin 500mg IV once daily: coverage for atypical CAP, including mycoplasma and</div><div class=\"answer-line\">legionella given cruise.</div><div class=\"answer-line\">Linezolid 600mg IV bd, OR Vancomycin 1g IV once daily (dosing modification): coverage</div><div class=\"answer-line\">for MRSA in a post-Influenza MRSA pneumonia</div><div class=\"answer-line\">Oseltamivir 75mg oral bd: coverage for severe influenza.</div><div class=\"answer-line\">Meropenem 1g IV tds: coverage for Melioidosis given travel to Northern Australia</div><div class=\"answer-line\"><strong>Marking criteria: must cover Meliodosis. </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Trauma</div><div class=\"answer-line\">Burns</div><div class=\"answer-line\">Pancreatitis</div><div class=\"answer-line\">Aspiration</div><div class=\"answer-line\">Massive Transfusion</div><div class=\"answer-line\">Fat Embolus</div><div class=\"answer-line\">Near Drowning</div><div class=\"answer-line\">Non-respiratory Sepsis</div><div class=\"answer-line\">Lung contusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bronchodilators: Given asthma history ; Salbutamol 5mg neb, continuous Atrovent</div><div class=\"answer-line\">500mcg (burst q20mins or q4h) + Hydrocortisone 200mg stat.</div><div class=\"answer-line\">Step-wise increase in supplemental oxygen: NRB 15L -&gt; HFNC 1-2L/kg max 50L/min and</div><div class=\"answer-line\">maximal FiO2.</div><div class=\"answer-line\">Commenced NIV with BiPAP ; initial setting EPAP 6, PS 12. FiO2 1.0</div><div class=\"answer-line\">DSI for pre-oxygenation: carefully titrated ketamine to facilitate NIV pre-oxygenation;</div><div class=\"answer-line\">remain upright position until intubation.</div><div class=\"answer-line\">Intubation : experienced operator; preferably Sz 8.0 ETT to allow bronchoscopy.</div><div class=\"answer-line\">Ventilate using ARDSnet approach : Vt 4-6ml/kg, FiO2 1.0. ; Target plateau pressure</div><div class=\"answer-line\">&lt;30mmHg with permissive hypercapnoea</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 70-year-old woman presents to your Emergency Department with sudden loss of vision in her left eye. This happened 2 hours prior to her presentation and is painless. There is no history of trauma. She is assessed by one of your junior doctors who is concerned about a possible vascular cause. She asks you to help her differentiate a retinal vein occlusion from a retinal artery occlusion.","parts":[{"id":"a","label":"Part A","prompt":". Compare and contrast the two conditions by filling in the table below. For each condition, provide two (2) risk factors/causes, the expected fundoscopy findings and name two (2) investigations that would be performed or initiated in the ED. (10 marks) Condition Central Retinal Artery Central Retinal Vein Occlusion Occlusion Major Risk Factors/Causes Fundoscopy findings ED investigations"},{"id":"b","label":"Part B","prompt":". List two other causes of painless unilateral vision loss. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td><strong>Major Risk </strong></td><td>Atherosclerotic emboli Hypertension</td></tr><tr><td><strong>Factors/Causes </strong></td><td>Infective emboli (Infective Diabetes</td></tr><tr><td><strong>(2 marks) </strong></td><td>endocarditis) Glaucoma</td></tr><tr><td>Vasculitis – SLE/GCA</td><td>Hypercoagulability</td></tr><tr><td><strong>Fundoscopy findings</strong></td><td>Pale fundus Retinal haemorrhages</td></tr><tr><td><strong>(1 mark) </strong></td><td>Cherry red fovea Tortuous, engorged retinal veins</td></tr><tr><td><strong>ED investigations </strong></td><td>Inflammatory markers (if BSL</td></tr><tr><td><strong>(2 marks) </strong></td><td>vasculitis suspected) IOPs</td></tr><tr><td>Embolic work-up – TTE/Carotid</td><td>Coag profile (if young)</td></tr><tr><td>dopplers</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vitreous humour haemorrhage <strong> </strong></div><div class=\"answer-line\">Retinal detachment<strong> </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 36-year-old lady is brought in by her husband who is concerned that she is ‘not herself’. Her GP has been investigating her for irritability, weight loss, palpitations and fatigue. The following tests are available: TSH 0.2mlU/L (0.4-5mlU/L) T4 20mcg/dL (5-11mcg/dL)","parts":[{"id":"a","label":"Part A","prompt":". Provide a diagnosis and list four (4) possible aetiologies . (5 marks) On assessment she appears restless and anxious. A set of vital signs are performed; her heart rate is 160 bpm, BP 91/57 mmHg, temperature 38 degrees Celsius."},{"id":"b","label":"Part B","prompt":". List six (6) differential diagnoses that must be considered. ( 3 marks) You conclude that her current symptomatology is caused by her thyroid disorder."},{"id":"c","label":"Part C","prompt":". List and prioritise the medical treatments required, with a justification (4 marks) Treatment Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Blood results consistent with hyperthyroididsm and clinical picture of thyrotoxicosis</div><div class=\"answer-line\">Primary- Grave’s disease, toxic multinodular goitre, toxic adenoma</div><div class=\"answer-line\">Thyroiditis- radiation, post-partum</div><div class=\"answer-line\">Drug induced- Lithium, amiodarone</div><div class=\"answer-line\">Central hyperthyroidism- pituitary adenoma, ectopic thyroid tissue</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Thyroid storm</div><div class=\"answer-line\">Sepsis</div><div class=\"answer-line\">Heat stroke</div><div class=\"answer-line\">Drug withdrawal</div><div class=\"answer-line\">Neuroleptic syndrome</div><div class=\"answer-line\">Sympathomimetic ingestion</div><div class=\"answer-line\">Malignant hyperthermia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>b-blocker</td><td>decreases morbidity and mortality, inhibits</td></tr><tr><td>- IV propranolol 0.5mg to 10mg, then 40-</td><td>peripheral conversion T4to T3, antagonises</td></tr><tr><td>120mg qid po</td><td>the effects of thyroid hormones and decreases</td></tr><tr><td colspan=\"2\">the sensitivities to catecholamine</td></tr><tr><td>Thyroid blocking drugs</td><td>- prevents hormone synthesis by by blocking</td></tr><tr><td>propylthiouracil 900-1200mg po, then</td><td>iodination of tyrosine and inhibits peripheral</td></tr><tr><td>200mg q4h</td><td>conversion T4 to T3</td></tr><tr><td>Iodine (lugols iodine) 60 drops daily in</td><td>- prevents hormone synthesis by by blocking</td></tr><tr><td>divided doses</td><td>iodination of tyrosine and inhibits peripheral</td></tr><tr><td>Lithium if allergic to iodine</td><td>conversion T4 to T3</td></tr><tr><td>Corticosteroids- Hydrocortisone 100mg</td><td>inhibit peripheral conversion T4 to T3</td></tr><tr><td colspan=\"2\">IV qid</td></tr><tr><td>correct fluid loss, electrolyte</td><td>Supportive measures-</td></tr><tr><td colspan=\"2\">abnormalities, cool hyperthermia</td></tr><tr><td colspan=\"2\">Avoid NSAIDS (displace T4 from binding proteins), treat precipitating cause</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 34-year-old female, primigravida at 34/40 gestation presents to your ED. She has been having regular painful contractions for the past hour, occurring at 3-minute intervals. She reports ruptured membranes about 30 minutes ago and is feeling the need to push. Your hospital does NOT have an obstetric or neonatal service. The nearest tertiary centre is 220 km away.","parts":[{"id":"a","label":"Part A","prompt":". Complete the table below listing three (3) medications and three (3) pieces of equipment you will prepare to manage this patient in your ED. (6 marks) Medications Equipment A male infant is born shortly after arrival by an uneventful delivery. At 1 minute, his APGAR score is 6. APGAR SCORE Appearance Peripheral cyanosis only > 100 Pulse rate Reflex irritability Grimace, weak cry when stimulated Tone Some flexion Respiration Slow irregular breathing"},{"id":"b","label":"Part B","prompt":". List 6 measures that will need to be instituted in the immediate post-delivery period for this neonate. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Oxytocin 10 Units IMI</td><td>Delivery pack with cord clamps</td></tr><tr><td>Betamethasone 11.4mg IMI</td><td>Neonatal resuscitaire with Neopuff or</td></tr><tr><td>OR Dexamethasone 10mg IV</td><td>similar positive pressure ventilation</td></tr><tr><td colspan=\"2\">device</td></tr><tr><td>Tocolytic agents:</td><td>Ultrasound to check fetal HR and</td></tr><tr><td>Salbutamol nebs 5mg or IV infusion</td><td>position</td></tr><tr><td>Nifedipine  oral 20mg q30 minutely (up</td><td>Towels, Suction etc.</td></tr><tr><td colspan=\"2\">to total of 3 doses)</td></tr><tr><td colspan=\"2\">OR</td></tr><tr><td colspan=\"2\">Also accept Antibiotics, given PPROM</td></tr><tr><td colspan=\"2\">Ampicillin 2g &amp; Gentamycin 5mg/kg IV</td></tr><tr><td colspan=\"2\">A male infant is born shortly after arrival with an uneventful delivery. At 1 minute, his APGAR score is 6.</td></tr><tr><td colspan=\"2\"><strong>APGAR SCORE </strong></td></tr><tr><td>Appearance</td><td><strong>Peripheral cyanosis only </strong></td></tr><tr><td>Pulse rate</td><td><strong>&gt; 100</strong></td></tr><tr><td>Reflex irritability</td><td><strong>Grimace, weak cry when stimulated </strong></td></tr><tr><td>Tone</td><td><strong>Some flexion </strong></td></tr><tr><td colspan=\"2\"><strong>Slow irregular breathing  </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Dry and stimulate the infant</div><div class=\"answer-line\">Warming (radiant heat +/- wrap in polyethylene bag)</div><div class=\"answer-line\">Positive pressure ventilator support with Neopuff (or similar device) using room air</div><div class=\"answer-line\">Maintain open airway</div><div class=\"answer-line\">Suctioning secretions from oropharynx</div><div class=\"answer-line\">Check BSL early and replace glucose if BSL &lt; 3.0</div><div class=\"answer-line\">Antibiotics – Ampicillin 50mg/kg and Gentamycin 5mg/kg IV (as most likely cause for</div><div class=\"answer-line\">preterm labour is infection)</div><div class=\"answer-line\">Vitamin K</div><div class=\"answer-line\"><strong>SCHHS-METRO NORTH </strong></div><div class=\"answer-line\"><strong>MOCK FELLOWSHIP SAQ EXAM </strong></div><div class=\"answer-line\"><strong>2019.1</strong></div><div class=\"answer-line\"><strong>BOOKLET TWO </strong></div><div class=\"answer-line\"><strong>QUESTIONS 10-18 </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"(18 marks) A 26-year-old man presents to triage with a chest wound following an altercation at a local bar (see image in the Props Booklet; Figure 4). He is immediately laid down on a trolley and transferred to the resuscitation bay where he arrests as the monitoring is being attached.","parts":[{"id":"a","label":"Part A","prompt":"Describe your immediate management for this patient. (2 marks) After your interventions, the patient achieves ROSC. Due to ongoing bleeding, you activate the hospital Massive Transfusion Protocol (MTP)."},{"id":"b","label":"Part B","prompt":". List two other indications apart from trauma for the in-hospital activation of the Massive Transfusion Protocol (MTP). (2marks)"},{"id":"c","label":"Part C","prompt":". Complete the following table for parameters to monitor during a massive transfusion, and their desired\ntarget ( 8 marks)"},{"id":"d","label":"Part D","prompt":". State the post resuscitation cares required. (6 marks)"}],"propPages":["asset:imgff1b3fce5029f2c3ff"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Finger thoracostomy: on the right (formalise to tube thoracostomy when able) </strong></div><div class=\"answer-line\">Needs intubation, if tube not immediately placed.</div><div class=\"answer-line\">IV expansion: Blood if available , N/saline otherwise</div><div class=\"answer-line\"><strong>Marking criteria: Some candidates may recommend a resuscitative thoracotomy.  That would be an </strong></div><div class=\"answer-line\"><strong>inappropriate, excessive response to a right sided, mid-axillary stab wound. </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Actual or anticipated 4 units RBC in &lt; 4 hrs, + haemodynamically unstable  +/– anticipated</div><div class=\"answer-line\">ongoing bleeding</div><div class=\"answer-line\">Major obstetric, gastrointestinal or surgical bleeding</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Haematological</td><td>Ca2+ &gt;1.1mmol/L</td></tr><tr><td colspan=\"2\">Platelets &gt;50 x109/L</td></tr><tr><td colspan=\"2\">PT/APTT &lt;1.5 x normal</td></tr><tr><td colspan=\"2\">INR &lt;1.5</td></tr><tr><td colspan=\"2\">Fibrinogen &gt; 1.0g/L (&gt;2.5g/L for PPH)</td></tr><tr><td>Acid-Base</td><td>pH &gt;7.2</td></tr><tr><td colspan=\"2\">Base excess &lt; -6</td></tr><tr><td colspan=\"2\">Lactate &lt;4mmol/L</td></tr><tr><td>Temperature</td><td>Temp &gt;35°C</td></tr><tr><td colspan=\"2\"><strong>Marking criteria: Candidates should include elements from all sections. </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Prevent further</td></tr><tr><td colspan=\"2\">cardiac arrest</td></tr><tr><td colspan=\"2\">Confirm Airway position and patency</td></tr><tr><td colspan=\"2\">Lung protective ventilation strategy: SpO2 94-98% (avoid hyper</td></tr><tr><td colspan=\"2\">or hypo-oxia), PACO2 35-45 mmHg</td></tr><tr><td colspan=\"2\">Ensure patency of ICC</td></tr><tr><td colspan=\"2\">Minimum volume resuscitation: Blood rather than crystalloid,</td></tr><tr><td colspan=\"2\"><strong>Permissive hypotension (SBP 80mmHg)</strong></td></tr><tr><td colspan=\"2\">Sedation &amp; analgesia (ketamine 1mg/kg/hr IV)</td></tr><tr><td colspan=\"2\">BSL: 4-10mmol/L (Normo-glycaemia)</td></tr><tr><td>Define &amp; treat</td><td><strong>Trauma call/urgent surgical assessment : OT if unstable / maybe </strong></td></tr><tr><td>underlying</td><td><strong>CT if stable </strong></td></tr><tr><td colspan=\"2\">pathology:</td></tr><tr><td>Limit secondary</td><td>Normothermia (~36°C)</td></tr><tr><td colspan=\"2\">insult:</td></tr><tr><td colspan=\"2\"><strong>Marking criteria: Candidates should include frequent re-evaluation, permissive hypotension, and  surgical </strong></td></tr><tr><td colspan=\"2\"><strong>involvement/expedited theatre </strong></td></tr><tr><td colspan=\"2\">Ref:</td></tr><tr><td colspan=\"2\">ANZCOR Post-Resus therapy 2016</td></tr><tr><td colspan=\"2\">National Blood Authority. Patient Blood Management Guidelines: Module 1 – Critical Bleeding/Massive</td></tr><tr><td colspan=\"2\">Transfusion. [cited 2011 Jun 30].</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"(18 marks) A 58-year-old female is brought to your emergency department complaining of having been bitten on the hand by a brown-coloured snake three hours ago. The ambulance service has applied a pressure immobilisation bandage.","parts":[{"id":"a","label":"Part A","prompt":". List the clinical assessment features that would suggest envenomation in this case. ( 4 marks) Her initial coagulation profile is shown below."},{"id":"b","label":"Part B","prompt":". Define the abnormality shown. (1 mark) . The advice from the toxicologist is to perform a venom detection kit (VDK) test."},{"id":"c","label":"Part C","prompt":". List three (3) options for sample acquisition and state the role of a VDK. (4 marks)"},{"id":"d","label":"Part D","prompt":". Complete the following table listing the absolute and relative indications for antivenom administration. (6 marks)"},{"id":"e","label":"Part E","prompt":". List three other considerations regarding the administration of antivenom (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Neurotoxicity- paralysis (presynaptic- does not improve with AV), progressive descending</div><div class=\"answer-line\">paralysis, ptosis, facial and bulbar involvement- paralysis extraocular muscles, respiratory</div><div class=\"answer-line\">muscles and peripheral weakness</div><div class=\"answer-line\">Myotoxicity- muscle pain, tenderness and weakness, increased CK and myoglobinuria</div><div class=\"answer-line\">Systemic symptoms- nausea, vomiting, headache, abdominal pain, diarrhoea, diaphoresis,</div><div class=\"answer-line\">apnoea</div><div class=\"answer-line\">Cardiovascular effects- sudden collapse, cardiac arrest, dizziness, hypotension, LOC</div><div class=\"answer-line\">Coagulopathy- local site bruising/bleeding, intracrainial/gastrointestinal/genitourinal</div><div class=\"answer-line\">haemorrhage</div><div class=\"answer-line\">Other- renal failure (MAHA), local pain, swelling, tissue injury</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Venom induced consumptive coagulopathy- inc INR/PT, inc d-dimer. Low/unrecordable</div><div class=\"answer-line\">fibrinogen.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Swab- best option if available</div><div class=\"answer-line\">Urine- option if can-not swab site site, or if cleaned</div><div class=\"answer-line\">Blood- not reliable option</div><div class=\"answer-line\">To asses for type of antivenom not confirmation of envenomation. Only use if snake type</div><div class=\"answer-line\">not able to be identified on geography/clinical syndrome/snake expert</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Hx sudden collapse, cardiac arrest or</td><td>systemic sx (vomiting, headache,</td></tr><tr><td>seizure</td><td>abdominal pain)</td></tr><tr><td>Abnormal INR</td><td>Abnormal aPTT</td></tr><tr><td>Evidence of paralysis with ptosis and/or</td><td>CK &gt; 1000U/L</td></tr><tr><td colspan=\"2\">opthalmoplegia</td></tr><tr><td colspan=\"2\">Leucocytosis/lymphopaenia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Only give IV ; Dilute 1:10 with NSaline and infuse over 15 minutes</div><div class=\"answer-line\">In cardiac arrest/life threatening effects- slow IV push</div><div class=\"answer-line\">1 vial AV for adults (and kids)</div><div class=\"answer-line\">No need for premedication administration- but must be administered in critical care area,</div><div class=\"answer-line\">hypotension in &lt;5%, anaphylaxis</div><div class=\"answer-line\">Serum sickness – rx steroids 50mg/d for 5/7 if occurs (not premed)</div><div class=\"answer-line\">FFP speeds recovery, but risk of blood products so only administer if coagulopathy and</div><div class=\"answer-line\">active bleeding</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 2-month-old girl is brought in to ED by her very worried parents. They describe an episode just after feeding where she seemed to stop breathing and went floppy and blue around the lips. It lasted approximately 20 seconds and resolved after they picked the baby up and blew at her face. The baby cried and has been behaving normally since.","parts":[{"id":"a","label":"Part A","prompt":". What is the clinical term used to describe this child’s presentation? (1 mark)"},{"id":"b","label":"Part B","prompt":". List 4 differential diagnoses for this presentation. (4 marks)"},{"id":"c","label":"Part C","prompt":". List 4 criteria that would stratify this event as low risk. (4 marks) On completion of your history and assessment you are satisfied that this is a LOW RISK presentation."},{"id":"d","label":"Part D","prompt":". List three (3) further investigation or management steps you will perform prior to discharge home. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">BRUE – brief, resolved, unexplained event</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Normal physiological response:  laryngospasm, gagging</div><div class=\"answer-line\">Inflicted injury: (shaken baby, drug overdose, Factitious illness by proxy or intentional</div><div class=\"answer-line\">suffocation)</div><div class=\"answer-line\">Infection : Pertussis, septicaemia, pneumonia, meningitis,</div><div class=\"answer-line\">Airway obstruction: congenital abnormalities, infection, hypotonia</div><div class=\"answer-line\">Abdominal: intussusception, strangulated hernia, testicular torsion</div><div class=\"answer-line\">Metabolic problems: hypoglycaemia, hypocalcaemia, hypokalaemia, other inborn errors</div><div class=\"answer-line\">of metabolism</div><div class=\"answer-line\">Cardiac disease: congenital heart disease, arrhythmias, vascular ring, prolonged QT.</div><div class=\"answer-line\">Respiratory: inhaled FB</div><div class=\"answer-line\">Toxin / Drugs: accidental or non-accidental</div><div class=\"answer-line\">Neurological causes: head injury, seizures, infections, cerebral malformations etc.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">age &gt;60 days</div><div class=\"answer-line\">gestational age ≥32 weeks and postconceptional age ≥45 weeks</div><div class=\"answer-line\">occurrence of only 1 BRUE (no prior BRUE ever and not occurring in clusters)</div><div class=\"answer-line\">duration of BRUE &lt;1 minute</div><div class=\"answer-line\">no cardiopulmonary resuscitation by trained medical provider required</div><div class=\"answer-line\">no concerning historical features</div><div class=\"answer-line\">no concerning physical examination findings</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Educate caregivers about BRUEs, and the low risk for infants with these characteristics.</div><div class=\"answer-line\">Offer resources for training in cardiopulmonary resuscitation (CPR).</div><div class=\"answer-line\">Arrange for a follow-up check with a medical provider within 24 hours to identify infants</div><div class=\"answer-line\">with evolving medical concerns that would require further evaluation and treatment.</div><div class=\"answer-line\">A brief period of in-hospital observation (eg, one to four hours – or even overnight given</div><div class=\"answer-line\">time of presentation) with continuous pulse oximetry and serial observations.</div><div class=\"answer-line\">12-lead electrocardiogram with attention to QT interval</div><div class=\"answer-line\">Testing for pertussis (especially for infants with suggestive symptoms). Respiratory virus</div><div class=\"answer-line\">testing, such as for respiratory syncytial virus, is reasonable if a rapid testing method is</div><div class=\"answer-line\">available. However, this testing is not required in these low-risk infants, who by definition</div><div class=\"answer-line\">have no respiratory symptoms and are &gt;2 months of age.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"You have just started working as a junior consultant on a temporary contract in a metropolitan emergency department, hoping that your contract will become permanent. You are helping in the resuscitation of a patient where the team leader in this resuscitation is one of your senior FACEM colleagues who has worked at this emergency department for over 20 years, is an ACEM examiner and is very well respected. The patient is a 9-year-old male with Duchenne’s muscular dystrophy who has pneumonia and is in respiratory failure. Your colleague has told the team that the decision has been made to intubate this patient. He asks the nurse to draw up ketamine and suxamethonium for the intubation.","parts":[{"id":"a","label":"Part A","prompt":"What is your response to the choice of these drugs? (1 marks)"},{"id":"b","label":"Part B","prompt":"How would you communicate this to your senior colleague? (2marks)"},{"id":"c","label":"Part C","prompt":"State two barriers to effective communication with your colleague in this situation? (2 marks)"},{"id":"d","label":"Part D","prompt":"List the next steps of your communication strategy in this situation should your senior colleague not respond favourably to your initial communication? (2 marks)"},{"id":"e","label":"Part E","prompt":"List 3 principles of harm minimisation. (3 marks)"},{"id":"f","label":"Part F","prompt":"What is the study of human factors? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Concern that giving suxamethonium (succinylcholine) to a patient with a muscular dystrophy</div><div class=\"answer-line\">could result in suxamethonium-induced hyperkalaemia that may be life-threatening.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Communicate directly to your senior colleague</div><div class=\"answer-line\">outline your concerns and reasons behind them</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Many different answers but must include hierarchy effect</div><div class=\"answer-line\">+ one other (e.g. junior consultant; in vulnerable position re employment, senior colleague poor</div><div class=\"answer-line\">response to being challenged; organisation very hierarchical)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Any answer that outlines a graded assertiveness communication strategy that will stop the error</div><div class=\"answer-line\">from being made.</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">error is inevitable</div><div class=\"answer-line\">harm is <strong>not</strong> an inevitable consequence of error</div><div class=\"answer-line\">find out what is wrong, not who is wrong</div><div class=\"answer-line\">the person who has made the error is the person : least likely to make it again, most likely</div><div class=\"answer-line\">to provide the solution, most likely to prevent others from making the same error</div><div class=\"answer-line\">most team errors are communication errors</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">the study of how people interact with complex systems (two-way)</div><div class=\"answer-line\">how problems with those interactions lead to errors and breakdowns in safety</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 78-year-old woman presents to your tertiary hospital with nausea, vomiting, loose bowel motions and malaise. She has a background of atrial fibrillation, hypertension and type II diabetes. Her current medications include: Candesartan 16mg daily, apixaban 2.5mg bd, dapagliflozin 10mg od, lercanidipine 10mg daily, bisoprolol 10mg daily, simvastatin 40mg daily and linagliptin-metformin 2.5mg-1g bd. She has not taken any over the counter medications.\nHer observations on arrival are: BP 141/72, HR 90, RR 28, saturations 93% on RA, temperature 35.2 degrees\nCelsius. She is alert and oriented with a clear chest and soft-non-tender abdomen. Arterial blood gas and renal function are performed; the results are shown below:\n\nFiO2\n0.21\n\npH\n6.75 (7.35-7.45)\n\npCO2\n24mmHg (32-48)\n\npO2\n86 mmHg (83-108) Bicarbonate 3 mmol/L (22-32) Sodium 132 mmol/L (135-145) Potassium 6.4 mmol/L (3.5-5.2) Chloride 102 mmol/L (95-110)\n\nGlucose\n15.7 mmol/L (3.0 -7.8)\n\nLactate\n15.0 mmol/L (0.5-2.2)\n\nUrea\n14.6 mmol/L (3.0-8.0)\n\nCreatinine\n237 μmol/L (40-90)","parts":[{"id":"a","label":"Part A","prompt":". Analyse the above results, listing the major abnormalities and their clinical implication. Include calculations where relevant. (7 marks) Abnormality Interpretation"},{"id":"b","label":"Part B","prompt":". Give the most likely underlying aetiologies of the major acid-base abnormality. (1 mark)"},{"id":"c","label":"Part C","prompt":". List your management priorities. Give drug doses and end points where relevant. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Profound acidaemia</td><td>Metabolic with bicarbonate- of 3</td></tr><tr><td colspan=\"2\">Expected CO2= 1.5 x HCO3- + 8 = 12.5.</td></tr><tr><td colspan=\"2\">Mildly low pCO2 (24)</td></tr><tr><td colspan=\"2\"><strong>inadequate respiratory compensation</strong></td></tr><tr><td colspan=\"2\">= Na+ - (Cl- + HCO3--) = 27</td></tr><tr><td colspan=\"2\"><strong>Delta ratio</strong> = change in AG/change in HCO3- = 15/21 = 0.71.</td></tr><tr><td>High anion gap</td><td>Predominantly HAGMA + element of NAGMA</td></tr><tr><td colspan=\"2\"><strong>HAGMA due to combination of  metformin, lactate and </strong></td></tr><tr><td colspan=\"2\"><strong>uraem</strong>ia.</td></tr><tr><td colspan=\"2\"><strong>corrected to ~3.4 (</strong>Correcting for pH = ~0.5 K+ change for every</td></tr><tr><td>Hyperkalaemia</td><td>0.1 of pH )</td></tr><tr><td colspan=\"2\">Predominantly due to acidaemia, ± contributed to from AKI</td></tr><tr><td colspan=\"2\">Type B – in this setting most likely <strong>B2 (drugs</strong>) secondary to</td></tr><tr><td colspan=\"2\">Elevated lactate</td></tr><tr><td colspan=\"2\">metformin</td></tr><tr><td colspan=\"2\">Correcting for hyperglycaemia = 132 + (15.7-5)-3 = <strong>135 = in </strong></td></tr><tr><td colspan=\"2\">Mild hyponatraemia</td></tr><tr><td colspan=\"2\"><strong>normal</strong> range</td></tr><tr><td colspan=\"2\"><strong>Urea : creat ratio = 60 = acute renal injury </strong>(not just pre-renal)</td></tr><tr><td colspan=\"2\">Urea 34.6 and</td></tr><tr><td colspan=\"2\">No prior history of renal failure and current medication list</td></tr><tr><td colspan=\"2\">creatinine 687 = acute</td></tr><tr><td colspan=\"2\">suggest AKI<strong> </strong></td></tr><tr><td colspan=\"2\">renal failure</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Metformin-associated lactic acidosis + Acute renal failure impairing excretion of</div><div class=\"answer-line\">metformin and also contributing to acidaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Correct critical acidaemia: </strong>initially 1mEq/kg 8.4% sodium bicarb (50-100 mL)</div><div class=\"answer-line\"><strong>Urgent haemodialysis, </strong>likely in ICU</div><div class=\"answer-line\"><strong>Fluid resuscitation:</strong> start with 1L Hartmann’s and reassess perfusion/urine output.</div><div class=\"answer-line\">Treat underlying precipitant: hypothermic – culture and consider empiric antibiotics such</div><div class=\"answer-line\">as piperacillin/tazobactam 4.5g IV.</div><div class=\"answer-line\">Oxygen, titrate to sats &gt;94%</div><div class=\"answer-line\">Treat hyperkalemia (relative hyperkalemia is secondary to acidosis therefore correction of</div><div class=\"answer-line\">acidosis should be priority)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"An 8-year-old girl is brought to the emergency department following a bicycle accident. She was wearing a helmet but no other safety gear. The child states she crashed into a fallen tree and was impaled on a stick. She is alert and distressed. When asked to describe the stick she indicates it was the length of her forearm and as thick as her thumb.\nHer vital signs are:\nPulse 110 bpm\n\nBP 105/70 mmHg\n\nCap refill 3 sec\nResp rate 24 breaths/min\n\nSaO2 92% on 6L oxygen via non-rebreather mask\nExamination reveals a 10cm laceration to the right lateral abdomen at the level of umbilicus (see picture in Props Booklet; Figure 5).","parts":[{"id":"a","label":"Part A","prompt":"List eight potential injuries from the described mechanism.(4 marks)"},{"id":"b","label":"Part B","prompt":". List four(4) ways in which the paediatric abdomen is different to the adult abdomen. (4 marks)"},{"id":"c","label":"Part C","prompt":". State your management of this patient in the ED, including relevant investigations.(6 marks)"}],"propPages":["asset:img855d4b0140d764e532"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Thoracic:</td><td>Haemothorax</td></tr><tr><td colspan=\"2\">Pneumothorax</td></tr><tr><td colspan=\"2\">Pulmonary contusion or laceration</td></tr><tr><td colspan=\"2\">Diaphragmatic perforation</td></tr><tr><td colspan=\"2\">Bronchopleural fistula</td></tr><tr><td colspan=\"2\">Cardiac contusion or laceration (unlikely given clinical</td></tr><tr><td colspan=\"2\">state)</td></tr><tr><td>Abdominal:</td><td>Hollow viscous perforation</td></tr><tr><td colspan=\"2\">Solid organ penetration (Liver, Kidney, unlikely splenic)</td></tr><tr><td colspan=\"2\">Vascular injury (IVC, abdominal aorta)</td></tr><tr><td colspan=\"2\">Ureteric laceration</td></tr><tr><td>Pelvic:</td><td>Bladder perforation</td></tr><tr><td colspan=\"2\">Uterine laceration</td></tr><tr><td colspan=\"2\">Ovarian injury</td></tr><tr><td colspan=\"2\"><strong>Marking criteria: Must have at least one injury each from chest, abdomen, pelvis. Any sensible injury </strong></td></tr><tr><td colspan=\"2\"><strong>acceptable. </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Small size of patient allows single impact to injure multiple organs.</div><div class=\"answer-line\">Abdominal wall is relatively thin</div><div class=\"answer-line\">Ribs are more pliable, providing less protection.</div><div class=\"answer-line\">Liver and spleen take up a larger proportion of the abdominal cavity.</div><div class=\"answer-line\">Diaphragm is more horizontal, pushing liver and spleen further into abdominal cavity.</div><div class=\"answer-line\">Bladder is an intra-abdominal organ in small children.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Seek and treat immediate life threats:  haemo-pneumothorax and hypovolaemia.</div><div class=\"answer-line\">Minimal volume resuscitation: End point: Cap refill &lt; 2sec; PRC 10ml/kg aliquots</div><div class=\"answer-line\">Analgesia: Parenteral most appropriate in this patient</div><div class=\"answer-line\">Fentanyl 1mcg/kg q10 min until analgesia</div><div class=\"answer-line\">Morphine 0.1mg/kg q 15 min until analgesia</div><div class=\"answer-line\">Ketamine 0.2mg/kg repeat x2 if required</div><div class=\"answer-line\">Investigations: Radiological: CXR (portable) +/- CT(chest/abdo/pelvis) if stable to</div><div class=\"answer-line\">define injury</div><div class=\"answer-line\">Investigations: Bloods: VBG – for lactate; Cross match</div><div class=\"answer-line\">Urgent notification to General/Trauma Surgeons: High risk penetrating abdominal</div><div class=\"answer-line\">injury; Requires OT for laparotomy.</div><div class=\"answer-line\">IV Ab’s: Ampicillin 50mg/kg qid + Gentamicin 5mg/kg od + Metronidazole 12.5mg/kg</div><div class=\"answer-line\">bd</div><div class=\"answer-line\">NBM +/- NGT</div><div class=\"answer-line\">Check immunisation for ADT and manage accordingly</div><div class=\"answer-line\"><strong>Marking criteria: </strong>Paediatric Trauma Service Guidelines, LCCH (2016) p26 states: N/Saline as the initial fluid in</div><div class=\"answer-line\">10ml/kg aliquots; Blood products (10ml/kg) to be given after saline resuscitation.;I think it reasonable to</div><div class=\"answer-line\">start with either.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 42-year-old female presents with fever five days after induction chemotherapy. Other than her malignancy she has no medical problems but does suffer from a rash when given penicillins.\nHer vital signs are as follows:\n\nHR\n110bpm\n\nBP\n100/60mmHg\n\nTemp 39.0 degrees Celsius\n\nSaO2\n98% room air\n\nRR\n24 breaths/min You assume she is neutropenic and decide to treat empirically.","parts":[{"id":"a","label":"Part A","prompt":". List two (2) options for the preferred antibiotic monotherapy for this patient. (1 mark)"},{"id":"b","label":"Part B","prompt":". List three (3) risk factors for tumour lysis syndrome (3 marks)"},{"id":"c","label":"Part C","prompt":". List three (3) metabolic features of tumour lysis syndrome other than renal impairment and hyperuricaemia (3 marks) There is a prolonged wait for the patient to get seen by the oncology team and you are concerned that she will deteriorate if her hyperuricaemia goes untreated."},{"id":"d","label":"Part D","prompt":". List two (2) interventions to treat hyperuricaemia secondary to tumour lysis syndrome in the ED. (1 mark) The oncology registrar finally comes down to see the patient. The nurse attending to the patient comes to find you as the patient complained that the oncology registrar was abrupt and dismissive towards her and the patient is now crying."},{"id":"e","label":"Part E","prompt":". How will manage this situation? (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cefepime 2g iv OR</div><div class=\"answer-line\">Ceftazidime 2g iv OR</div><div class=\"answer-line\">Meropenem 1g iv</div><div class=\"answer-line\">ETG: https://www.eviq.org.au/clinical-resources/oncological-emergencies/123-immediate-management-of-</div><div class=\"answer-line\">neutropenic-fever#management</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">High tumour proliferation rates</div><div class=\"answer-line\">Large tumour burden</div><div class=\"answer-line\">Sensitivity to chemotherapy</div><div class=\"answer-line\">Haematological malignancy</div><div class=\"answer-line\">Bulky disease (&gt;10cm diameter)</div><div class=\"answer-line\">Leukocytosis (&gt;25x10^6)</div><div class=\"answer-line\">Pre-existing renal impairment</div><div class=\"answer-line\">Pre-existing hyperuricaemia</div><div class=\"answer-line\">Jonathan Wagner and Sanjay Arora, Oncologic Metabolic Emergencies, Emergency Medicine Clinics of North</div><div class=\"answer-line\">America, 2014-08-01, Volume 32, Issue 3, Pages 509-525,</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hyperkalaemia</div><div class=\"answer-line\">Hyperphosphataemia</div><div class=\"answer-line\">Lactic acidosis</div><div class=\"answer-line\">Hypocalcaemia</div><div class=\"answer-line\">Dunn, Tintinalli</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Allopurinol OR Rasburicase</div><div class=\"answer-line\">Iv hydration (must have)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Speak to patient: apologise, elaborate, reassure that you will investigate and follow up with them</div><div class=\"answer-line\">Speak to registrar: inform of patient’s complaint, give opportunity to explain/apologise</div><div class=\"answer-line\">Document complaint in notes, risk management system</div><div class=\"answer-line\">Inform oncology consultant, ED director</div><div class=\"answer-line\">Complete the complaint process : investigate, take actions etc</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 60-year-old man presents with a syncopal episode whilst at work. He is unable to describe any preceding symptoms and recalls upon waking up his colleagues standing around him. He is currently asymptomatic. His ECG is shown in the Props Booklet (Figure 6)","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities found on his ECG (4 marks)\nAfter your initial assessment your patient deteriorates and becomes markedly bradycardic. His formal vitals are:\n\nGCS\n\nHR\n28 bpm\n\nBP\n70/40 mm Hg\n\nSaO2\n88% on room air\n\nRR\n28breaths/mon Temperature 36.5 degrees Celsius"},{"id":"b","label":"Part B","prompt":"List 2 reversible causes of his bradycardia (2 marks)"},{"id":"c","label":"Part C","prompt":"List 6 steps in management for this patient (6 marks)"}],"propPages":["asset:img5278232169ec156486"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Bradycardia at approximately 45bpm</td></tr><tr><td colspan=\"2\">Irregular rhythm/Sinus Arrhythmia</td></tr><tr><td colspan=\"2\"><strong>Left Axis Deviation/Left Anterior Fascicular Block</strong></td></tr><tr><td colspan=\"2\">1st degree AV block</td></tr><tr><td colspan=\"2\"><strong>Right bundle branch block</strong></td></tr><tr><td colspan=\"2\"><strong>Bifascicular block</strong></td></tr><tr><td colspan=\"2\">*must state Bifascicular block OR both Right bundle branch block with Left Anterior Fascicular block to score</td></tr><tr><td colspan=\"2\">any marks*</td></tr><tr><td colspan=\"2\">After your initial assessment your patient deteriorates and becomes markedly bradycardic.</td></tr><tr><td colspan=\"2\">His formal vitals are:</td></tr><tr><td>GCS</td><td>13</td></tr><tr><td>HR</td><td>28 bpm</td></tr><tr><td>BP</td><td>70/40 mmHG</td></tr><tr><td colspan=\"2\">SaO2</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Drugs; B-Blockers, Calcium Channel Blockers (not the dihydropyridines), digoxin,</div><div class=\"answer-line\">amiodarone, Clonidine, Organophosphates</div><div class=\"answer-line\">Electrolytes; Potassium</div><div class=\"answer-line\">Ischaemia</div><div class=\"answer-line\">Myocarditis</div><div class=\"answer-line\">Hypothyroidism</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Place patient on 15L O2 via non-rebreathing mask, aim SaO2 &gt;94%<strong> </strong></div><div class=\"answer-line\">Atropine IV 600mcg every 3-5 minutes to max total dose of 3mg. Aim for HR &gt; 60 and BP</div><div class=\"answer-line\">&gt;90mmHg or MAP &gt;65mmHg<strong> </strong></div><div class=\"answer-line\">2nd line drug therapy either Adrenaline IV infusion (2-10mcg/min). Aiming for HR&gt; 60 and</div><div class=\"answer-line\">BP &gt;90mmHg or MAP &gt;65mmHg OR Isoprenaline IV infusion (2-5mcg/min). Aiming for &gt;</div><div class=\"answer-line\">60 and BP &gt;90mmHg or MAP &gt;65mmHg<strong> </strong></div><div class=\"answer-line\">Correct under lying causes;  optimise electrolytes K &gt; 4 Mg &gt;1<strong> </strong></div><div class=\"answer-line\">Specific toxicology therapy: B-Blockers/Calcium Channel blockers; high dose insulin,</div><div class=\"answer-line\">glucagon,  Digoxin; Digibind<strong> </strong></div><div class=\"answer-line\">Ischaemia; PCI/Thrombolysis<strong> </strong></div><div class=\"answer-line\">Failure to respond to pharmacotherapy will require external cardiac pacing at 70bpm</div><div class=\"answer-line\">aiming for both electrical and mechanical capture at BP &gt;90mmHg or MAP &gt;65mmHg.</div><div class=\"answer-line\">Analgesia with pacing; fentanyl IV 25mcg aliquots q5 mins to comfort; Sedation with</div><div class=\"answer-line\">pacing; midazolam IV 1mg q5mins to comfort<strong> </strong></div><div class=\"answer-line\">Admission under cardiology for consideration of pacing wire/pacemaker<strong> </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 23-month old boy is brought in by his mother after ingesting an unknown quantity of her iron tablet thirty minutes ago. The child was found with 3 tablets remaining from a bottle that was previously around half full.","parts":[{"id":"a","label":"Part A","prompt":". Complete the following table for the dose-related risk assessment of iron (4 marks) Elemental iron dose (mg/kg) Effect One hour later, the child starts vomiting profusely and you are concerned he has had a significant ingestion\n• f iron."},{"id":"b","label":"Part B","prompt":". Complete the following table listing four (4) investigations you would perform and the corresponding result that would confirm significant iron ingestion. (4 marks)"},{"id":"c","label":"Part C","prompt":". List two (2) methods of decontamination that are used in iron overdose and state when they would be used. (2 marks) You consult with the on-call toxicologist who recommends starting chelation therapy."},{"id":"d","label":"Part D","prompt":". State the drug and dose of the chelation therapy used in significant iron toxicity. (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>&lt;20</td><td>Asymptomatic</td></tr><tr><td>20-60</td><td>GI symptoms</td></tr><tr><td>60-120</td><td>Systemic toxicity anticipated</td></tr><tr><td colspan=\"2\">&gt;120</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Abdominal Xray</td><td>Multiple tablets with &gt;40-60 mg/kg total</td></tr><tr><td colspan=\"2\">elemental iron</td></tr><tr><td>Serum iron concentration</td><td>Rising levels, serum iron concentration at</td></tr><tr><td colspan=\"2\">presentation and at ~4 hrs &gt;60-90 micromol/L</td></tr><tr><td>Blood gas</td><td>HAGMA</td></tr><tr><td>LFTS and Coags</td><td>Hepatic failure</td></tr><tr><td>UEC</td><td>Renal failure</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Whole bowel irrigation indicated for confirmed ingestions &gt; 60 mg/kg (difficult and</div><div class=\"answer-line\">potentially hazardous in small children)</div><div class=\"answer-line\">Surgical or endoscopic removal of tablets if lethal ingestion (e.g. &gt;120mg/kg) or WBI not</div><div class=\"answer-line\">feasible</div><div class=\"answer-line\">Clinical features and investigation results confirm significant iron poisoning with systemic toxicity. You</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Desferrioxamine i.v.i. 15-40 mg/kg/hr</div><div class=\"answer-line\"><strong>SCHHS-METRO NORTH </strong></div><div class=\"answer-line\"><strong>MOCK FELLOWSHIP SAQ EXAM </strong></div><div class=\"answer-line\"><strong>2019.1</strong></div><div class=\"answer-line\"><strong>BOOKLET THREE </strong></div><div class=\"answer-line\"><strong>QUESTIONS 19 - 27 </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"(18 marks) A 62-year-old female is brought into the resuscitation area of your department by ambulance. She woke from sleep this morning and felt dizzy and short of breath. She has a past medical history of end-stage renal failure secondary to diabetic nephropathy and has haemodialysis through a vas-cath three times a week. She has a left breast mastectomy for cancer 12 months ago and has a left above knee amputation from complications of her diabetes. On assessment, her vital signs are:\nTemperature 36.5 degrees Celsius\n\nBP\n120/80 mm Hg\n\nHR\n43 bpm regular\n\nSaO2\n95% RA\n\nRR\n16 breaths/min","parts":[{"id":"a","label":"Part A","prompt":". List 5 potential cause of her shortness of breath given the above history and justify each cause (5 marks) Cause Justification"},{"id":"b","label":"Part B","prompt":", List four (4) investigations that may help delineate the diagnosis and justify each (4 marks) Investigation Justification A venous blood gas is taken on room air and the results shown below.\n\nFiO2\n0.21\n\npH\n7.31 (7.32-7.43)\n\nPaCO2\n(38-54)\n\nPaO2\n(30-50)\n\nHCO3-\n(22-32)\n\nNa\n143 (135-145)\n\nK\n7.9 (3.5-5.2)\n\nGlucose\n24.5 (3.0 -7.8)\n\nLactate\n6.5 (0.5-2.2) You are about to give the patient calcium resonium when she has a PEA arrest, ALS is commenced."},{"id":"c","label":"Part C","prompt":". List the specific treatment of hyperkalemic cardiac arrest in this patient. (4 marks) ILCOR recommends modification to the ALS algorithm in certain special situations."},{"id":"d","label":"Part D","prompt":". Give five (5) examples of these special situations and state a recommendation or modification to the ALS algorithm for each example. (5 marks) Special situation Recommendation/Modification to ALS"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Pulmonary Oedema</td><td>Dialysis pt – susceptible to fluid overload</td></tr><tr><td>PE</td><td>Past Hx Ca also relatively immobile AKA –</td></tr><tr><td colspan=\"2\">increase risk VTE</td></tr><tr><td>Infection (Pneumonia / others accepted)</td><td>Immobility – relative immobile and immune</td></tr><tr><td colspan=\"2\">compromise diabetes</td></tr><tr><td>IHD / AMI</td><td>Bradycardiac ; diabetic patients can have</td></tr><tr><td colspan=\"2\">AMI with no chest pain</td></tr><tr><td>Pericardial effusion/tamponade</td><td>ESRF ? uraemic and risk of large pericardial</td></tr><tr><td colspan=\"2\">effusions</td></tr><tr><td colspan=\"2\">Other sensible answers will be accepted</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>ECG</td><td>Features of AMI / ischaemia -delineate HR</td></tr><tr><td colspan=\"2\">43/ Strain pattern – PE features s1q3t3</td></tr><tr><td>CXR</td><td>Features of oedema / infection</td></tr><tr><td>CTPA</td><td>If considering PE</td></tr><tr><td>ECHO</td><td>Features of RC strain (PE)</td></tr><tr><td colspan=\"2\">Pericardial effusion</td></tr><tr><td>Caridiac biomarker (TNI)</td><td>Elevated troponin (borderline TNI unhelpful</td></tr><tr><td colspan=\"2\">given ESRP but massively elevate would be</td></tr><tr><td colspan=\"2\">suggestive for AMI)</td></tr><tr><td colspan=\"2\">A venous blood gas is taken on room air and the results shown below.</td></tr><tr><td>FiO2</td><td>0.21</td></tr><tr><td>pH</td><td>7.31</td></tr><tr><td>PaCO2</td><td>46</td></tr><tr><td>PaO2</td><td>20</td></tr><tr><td>HCO3-</td><td>22</td></tr><tr><td>Na</td><td>143</td></tr><tr><td>K</td><td>7.9</td></tr><tr><td>Anion gap</td><td>21</td></tr><tr><td>Glucose</td><td>24.5</td></tr><tr><td>Lactate</td><td>6.5</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Protect the heart: give 10 mL calcium chloride 10% IV by rapid bolus injection or 30ml of</div><div class=\"answer-line\">calcium gluconate</div><div class=\"answer-line\">Shift potassium into cells: Give glucose/insulin: 10 units short-acting insulin and 25 g</div><div class=\"answer-line\">glucose IV by rapid injection. Monitor blood glucose.</div><div class=\"answer-line\">Give sodium bicarbonate: 50 mmol IV by rapid injection (if severe acidosis or renal</div><div class=\"answer-line\">failure).</div><div class=\"answer-line\">Remove potassium from body: Consider dialysis for hyperkalaemic cardiac arrest resistant</div><div class=\"answer-line\">to medical treatment. Several dialysis modalities have been used safely and effectively in</div><div class=\"answer-line\">cardiac arrest, but this may only be available in specialist centres. 28 Consider use of a</div><div class=\"answer-line\">mechanical chest compression device if prolonged CPR is needed.</div><div class=\"answer-line\"><em>Modifications to cardiopulmonary resuscitation (ERC from ILCOR Guidelines 2015)</em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hypoxia</td><td>Early effective ventilation with supplemental oxygen</td></tr><tr><td>Trauma</td><td>Prioritise sequence of life-saving measures: hypoxia, tension</td></tr><tr><td>ptx, tamponade, mTP. Chest compressions should not delay</td><td></td></tr><tr><td>the treatment of reversible causes</td><td></td></tr><tr><td>PE</td><td>Fibrinolysis + prolonged CPR</td></tr><tr><td>After major cardiac surgery</td><td>Re-sternotomy within 5 minutes</td></tr><tr><td>VT/VF during cardiac cath</td><td>3 stacked shocks; mechanical CPR devices</td></tr><tr><td>Submersion</td><td>Prioritise oxygenation and ventilation</td></tr><tr><td>Hypokalemia</td><td>Rapid potassium + mag infusion</td></tr><tr><td>Hypothermia</td><td>Do not delay intubation</td></tr><tr><td>Check for signs of life for up to  1minute</td><td></td></tr><tr><td>Withhold drugs until&gt;30 degrees then double interval</td><td></td></tr><tr><td>VF: 3 shocks then delay until &gt;30</td><td></td></tr><tr><td>Tocins</td><td>HDIT, intralipid, ECMO</td></tr><tr><td>See ILCOR/ERC guideline 2015:</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"(18 marks) You are the consultant in charge of an urban district emergency department. You have just assessed a 42- year-old male who has sustained an isolated head injury from a bicycle accident.","parts":[{"id":"a","label":"Part A","prompt":". List five (5) acute complications of head injuries (5 marks) You decide to electively intubate him."},{"id":"b","label":"Part B","prompt":". List four (4) indications for intubation in the emergency department, for any patient. (4 marks) You successfully intubate this patient. While securing the tube, you notice he has become hypotensive to 80/50mmHg."},{"id":"c","label":"Part C","prompt":". Complete the following table for potential causes for post-intubation hypotension in ANY patient and state your immediate management for each cause listed. (5 marks) Cause Immediate Management Post-intubation, he is taken to CT for trauma imaging. CT brain shows an acute subdural haematoma."},{"id":"d","label":"Part D","prompt":". List the indications for surgery in patients with acute subdural haematomas (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Impact apnoea</div><div class=\"answer-line\">↑ICP</div><div class=\"answer-line\">Intracranial h/toma (EDH/SDH/ICH /contusion)</div><div class=\"answer-line\">Diffuse axonal injury</div><div class=\"answer-line\">Skull fractures</div><div class=\"answer-line\">Cranial nerve injury</div><div class=\"answer-line\">CSF Leak</div><div class=\"answer-line\">Neurogenic cardiac dysfunction/APO</div><div class=\"answer-line\">Haemorrhagic shock (neonates)</div><div class=\"answer-line\">Aspiration pneumonia</div><div class=\"answer-line\">Seizures</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Airway protection/maintenance</div><div class=\"answer-line\">Ventilation support</div><div class=\"answer-line\">Oxygenation support</div><div class=\"answer-line\">Neuroprotection</div><div class=\"answer-line\">Control of the combative patient</div><div class=\"answer-line\">Facilitate safe transfer of a patient</div><div class=\"answer-line\">Expected clinical course</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Acidosis</td><td>Hyperventilation, bicarbonate administration</td></tr><tr><td>Anaphylaxis</td><td>Adrenaline iv</td></tr><tr><td>Pericardial tamponade</td><td>Decompress</td></tr><tr><td>Breath stacking</td><td>Disconnect tube, compress chest, alter ventilator settings,</td></tr><tr><td>bronchodilators</td><td></td></tr><tr><td>Hypovolaemia</td><td>IV fluid bolus</td></tr><tr><td>Induction agent effect</td><td>Supportive management – fluid, pressors</td></tr><tr><td>Tension PTX</td><td>Finger thoracostomy</td></tr><tr><td>Electrolyte abnormalities</td><td>Identify and correct</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-     haematoma thickness &gt;10 mm</div><div class=\"answer-line\">-     &gt; 5mm midline shift regardless of GCS</div><div class=\"answer-line\">-     GSC &lt; 8</div><div class=\"answer-line\">-     drop in GCS ≥ 2 points</div><div class=\"answer-line\">-     development of papillary inequality</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 34-year-old woman self-presents with fever, headache, body aches and generalised malaise. She takes no regular medications and has a reported penicillin allergy (rash as a child). Her observations are as follows: RR 18 breaths/min, saturations 97% on RA, BP 100/55, HR 115 bpm, temperature 39.5 degrees Celsius. She is\n\nGCS 15/15. Weight approximately 60 kg.\nA Chest X-ray (CXR) is performed and is shown in the Props Booklet (Figure 7).","parts":[{"id":"a","label":"Part A","prompt":"List two positive and one negative findings on this CXR. (3 marks)"},{"id":"b","label":"Part B","prompt":"Provide the most likely diagnosis for this patient (1 mark)"},{"id":"c","label":"Part C","prompt":"List five other criteria required to make a formal diagnosis? (5 marks)"},{"id":"d","label":"Part D","prompt":"What is the empiric treatment recommended for this patient? (3 marks)"}],"propPages":["asset:imge327ac8cd603bd95e7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sternotomy wires</div><div class=\"answer-line\">Circular opacity in region of valve consistent with valve replacement or repair.</div><div class=\"answer-line\">Multiple small rounded opacities in both lung fields suspicious for septic emboli.</div><div class=\"answer-line\">No confluent consolidation seen</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">suspicion of infective endocarditis (most likely secondary to IVDU) / infection of prosthetic</div><div class=\"answer-line\">valve also possibility</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Duke’s: 2 major/1 major+ 3minor/5minor</div><div class=\"answer-line\">2 positive blood cultures with organisms consistent with IE (major)</div><div class=\"answer-line\">Endocardial involvement on ECHO -mass/abscess/new valve regurg (major)</div><div class=\"answer-line\">ECHO concerning for IE (minor)</div><div class=\"answer-line\">Vascular phenomena -emboli, skin lesions (minor)</div><div class=\"answer-line\">Immunologic phenomena- Osler’s nodes, Roth spots(minor)</div><div class=\"answer-line\">Risk factors: IVDU/ heart condition (minor)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Gentamicin 5mg/kg (300mg IV)</div><div class=\"answer-line\">Vancomycin 30mg/kg (1.8g)</div><div class=\"answer-line\">Cephazolin 2g IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"You are the DEMT and have received an email from the Head of Internal Medicine which states that one of the inpatient registrars has accused one of your ED registrars of being persistently rude and derogative towards them.","parts":[{"id":"a","label":"Part A","prompt":". State two (2) methods you would use to gather more information prior to talking to the emergency registrar: (2 marks)"},{"id":"b","label":"Part B","prompt":". List four (4) things to consider when talking about the allegation with the Emergency Registrar. (4 marks) After talking to the Emergency Registrar, you discover they are experiencing significant personal stress due to a close family member being diagnosed with a terminal illness."},{"id":"c","label":"Part C","prompt":". How would you manage this situation? (4 marks) You implement the above interventions."},{"id":"d","label":"Part D","prompt":". List two (2) steps required to finalize this complaint. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Interview colleagues (other consultants, nursing staff) discretely to obtain witness</div><div class=\"answer-line\">accounts if possible</div><div class=\"answer-line\">Meet/phone call with Medical Director to ascertain more details: Ask for specific dates</div><div class=\"answer-line\">and examples rather than generalized statements</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Private location, free from distractions</div><div class=\"answer-line\">Show genuine empathy for a colleague</div><div class=\"answer-line\">Enquire about physical/mental health issues</div><div class=\"answer-line\">Enquire about social stressors</div><div class=\"answer-line\">Listen to their side of the story and document</div><div class=\"answer-line\">Explain that their alleged behavior is inappropriate and cannot continue (even if they</div><div class=\"answer-line\">deny it)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Refer to GP or Employee Assistance Program for ongoing support</div><div class=\"answer-line\">Ask about Social supports</div><div class=\"answer-line\">Ask about drugs/alcohol/self-harm/suicidal ideation</div><div class=\"answer-line\">Ability to work</div><div class=\"answer-line\">Mandatory reporting requirements</div><div class=\"answer-line\">Offer them leave, be flexible with leave</div><div class=\"answer-line\">Ensure the Emergency Department Director is aware of the situation</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Provide discrete feedback to Medical Director and Head of Internal Medicine in a timely</div><div class=\"answer-line\">fashion, ensuring the Emergency Registrar’s confidentiality is maintained.</div><div class=\"answer-line\">Follow up with the Emergency Registrar</div><div class=\"answer-line\">Document the complaint and the outcome</div><div class=\"answer-line\">Consider implementing 360 feedback for all emergency registrars as part of your feedback</div><div class=\"answer-line\">processes</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 48-year-old man presents to your regional Emergency Department with 24 hours of dysphagia and fevers, and new respiratory distress. He has no past medical history and is not on any medications. On arrival, he is sitting upright and is reluctant to lie back on the bed. He is having difficulty swallowing his secretions and also has a mild stridor with a hoarse voice.\nHis vital signs are:\n\nBP\n140/80 mmHg\n\nHR\n90 bpm\n\nSpO2 99% room air\n\nTemp 37.8 degrees Celsius\n\nRR\n24 breaths/min The nearest tertiary centre is a 2 hour drive away by road. You obtain a lateral neck x-ray, shown in the\nProps Booklet (Figure 8).","parts":[{"id":"a","label":"Part A","prompt":". State the likely diagnosis and name the relevant positive finding on this radiograph (2 marks)"},{"id":"b","label":"Part B","prompt":". What is the most common causative organism for this patient’s diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":". What would be your anti-microbial of choice for this patient? (1 mark) The patient develops worsening stridor and distress within 20 minutes of arrival at your department. He is becoming increasingly agitated and his oxygen saturations start to drop. You make the decision to intubate the patient in the ED. There is no anaesthetist available."},{"id":"d","label":"Part D","prompt":". Complete the following table, listing the issues you might face during the intubation of this patient and how you would address these problems. (8 marks)"}],"propPages":["asset:img714dbb8948e3b2bbcd","asset:imged96e7fa2737f43732"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Acute epiglottitis</div><div class=\"answer-line\">Thumb-printing sign of epiglottis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Strep pneumoniae</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ceftriaxone <em>or</em> Cefotaxime 1g IV</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">how you would address these problems.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 60-year-old woman presents to your Emergency Department complaining of a severe gradual onset headache, blurring of her vision and new onset confusion.\nHer vital signs are:\n\nGCS 13\n(E3V4M6)\n\nRR\n20/min\n\nSaO2\n96% in room air\n\nHR\n\nBP\n190/130mmHg\n\nTemp\n37.0C You diagnose her with Hypertensive Encephalopathy.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses, other than Hypertensive Encephalopathy, you would consider for this woman’s presentation (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the definition of a Hypertensive Emergency? (1 mark)"},{"id":"c","label":"Part C","prompt":"What is the definition of a Hypertensive Urgency? (1 mark)"},{"id":"d","label":"Part D","prompt":"Complete the following table with 4 drugs you could use to treat this woman’s hypertension including a pro and a con for each drug chosen (4 marks) Drug Pro Con"},{"id":"e","label":"Part E","prompt":"State your treatment goal for this woman’s hypertension (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Intra-cranial haemorrhage (traumatic or atraumatic); sub-dural haematoma, extra-dural</div><div class=\"answer-line\">haematoma. <em>Do not accept subarachnoid haemorrhage</em></div><div class=\"answer-line\">Meningo-encephalitis</div><div class=\"answer-line\">Other intra-cranial infection; abscess, cerebral toxoplasmosis</div><div class=\"answer-line\">Space-occupying lesion; Primary or secondary neoplastic lesion</div><div class=\"answer-line\">Carotid artery dissection</div><div class=\"answer-line\">Haemorrhagic CVA  <em>Do not accept stroke or CVA</em></div><div class=\"answer-line\">Migraine</div><div class=\"answer-line\">Hypoglycaemia</div><div class=\"answer-line\">Toxicological; CO poisoning</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Systolic Blood Pressure &gt;180 or Diastolic Blood Pressure &gt;120 AND End-organ</div><div class=\"answer-line\">dysfunction.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Systolic Blood Pressure &gt;180 or Diastolic Blood Pressure &gt;120 WITHOUT end-organ</div><div class=\"answer-line\">dysfunction</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Nitroglycerin </strong></td><td>Fast onset Can cause headache</td></tr><tr><td><strong>SL  </strong></td><td>Doesn’t require intravenous line Tachyphylaxis</td></tr><tr><td><strong>Top  </strong></td><td>Do not use with sildenafil</td></tr><tr><td>Reflex tachycardia</td><td></td></tr><tr><td><strong>Nitroglycerin </strong></td><td>Titratable Can cause headache</td></tr><tr><td><strong>IV infusion  </strong></td><td>Rapid onset Tachyphylaxis</td></tr><tr><td>*Must use different pro/con if</td><td>Do not use with sildenafil</td></tr><tr><td>uses both IV and other</td><td>CI with Aortic stenosis</td></tr><tr><td>formulation of GTN*</td><td></td></tr><tr><td><strong>Magnesium </strong></td><td>Relatively safe Risk of hypermagnesia</td></tr><tr><td><strong>IV infusion </strong></td><td>Familiarity Time of onset</td></tr><tr><td>Less predictable effect</td><td></td></tr><tr><td><strong>Hydralazine IV </strong></td><td>Rapid onset Reflex tachycardia</td></tr><tr><td>Familiarity</td><td>Urinary retention</td></tr><tr><td><strong>Sodium Nitroprusside </strong></td><td>Rapid onset/offset Requires central access</td></tr><tr><td><strong>IV infusion </strong></td><td>Titratable Toxic metabolite</td></tr><tr><td>Avoid light</td><td></td></tr><tr><td><strong>Beta-blockers: </strong></td><td>Rapid onset Bradycardia</td></tr><tr><td><strong>Metoprolol IV </strong></td><td>Titratable *only accept bradycardia as pt</td></tr><tr><td><strong>Esmolol IV  </strong></td><td>Familiarity has HR of 60</td></tr><tr><td><strong>Labetolol IV </strong></td><td></td></tr><tr><td><strong>Phentolamine IV </strong></td><td>Rapid onset Tachycardia/risk arrhythmia</td></tr><tr><td>GI upset</td><td></td></tr><tr><td><strong>Nimodipine IV infusion </strong></td><td>Pronounced reduction in BP Tachycardia</td></tr><tr><td><strong>(1mg/hr) </strong></td><td>Titratable Headache</td></tr><tr><td>Nausea</td><td></td></tr><tr><td>*do not accept oral drugs</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Decrease MAP by 15-25%</div><div class=\"answer-line\">Within 1-2 hours</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"You are the consultant in charge of the paediatric section of a rural emergency department. A 5-year-old boy presents via the ambulance following an accident with a home barbecue, thirty minutes ago. The ambulance reports the family was cooking lunch on the barbecue which was set up inside the house due to rainy weather when the gas bottle exploded and started a fire. On assessment the boy has considerable soot on his face and there is severe swelling to his cheeks, lips, and eyelids.\nHis vital signs are:\n\nSaO2\n89% on 15L oxygen via non-rebreather Pulse 120 bpm\n\nCap refill\n3 seconds Resp rate 28 breaths/min You decide to intubate the patient for airway protection. You perform a rapid-sequence induction but are unable to visualise the cords using video laryngoscopy. You are unable to ventilate the child with a bag-valve mask or a laryngeal mask airway. The on-call anaesthetist is on the way but is still more than ten minutes away.","parts":[{"id":"a","label":"Part A","prompt":". State your immediate management. (5 marks)"},{"id":"b","label":"Part B","prompt":". List three (3) causes of impaired oxygenation in this patient, and their causes. (3 marks) The anaesthetist arrives and successfully intubates the patient."},{"id":"c","label":"Part C","prompt":". List your ventilator settings with a justification for this patient. (4marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Can’t intubate, can’t ventilate scenario. Child under 8 years old so needs jet</div><div class=\"answer-line\">insufflation.</div><div class=\"answer-line\">Perform Cannula Cricothyroidotomy: (2 marks)</div><div class=\"answer-line\">Extend the neck (shoulder roll) + Stabilise larynx with non-dominant hand + Access</div><div class=\"answer-line\">cricothyroid membrane with a dedicated 14/16 gauge cannula + Aim in caudal</div><div class=\"answer-line\">direction Confirm position by air aspiration using a syringe filled with saline</div><div class=\"answer-line\">Perform jet insufflation: (2 marks)</div><div class=\"answer-line\">Connect to either an adjustable pressure limiting device, set to lowest delivery</div><div class=\"answer-line\">pressure OR a 4Bar O2 source with flowmeter (match flow L/min to child’s age) and Y-</div><div class=\"answer-line\">connector. Cautiously increase inflation pressure/flowrate to achieve adequate chest</div><div class=\"answer-line\">expansion. Wait for full expiration before next inflation. Maintain upper airway</div><div class=\"answer-line\">patency to aid in expiration</div><div class=\"answer-line\"><strong>Marking criteria: Must recognise that the child is too young for a surgical airway, though these have been </strong></div><div class=\"answer-line\"><strong>described and successful in the paediatric age group.</strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Cellular hypoxia: Carbonmonoxide; Cyanide, (Methaemoglobinaemia)</div><div class=\"answer-line\">Bronchospasm: Secondary to fumes and minute particles.</div><div class=\"answer-line\">Atelectasis and airway obstruction: Smoke particles causes hypersecretion,</div><div class=\"answer-line\">inflammation, and mucosal sloughing.</div><div class=\"answer-line\">Lung contusions and alveolar trauma: Blast injuries.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">FiO2 1.0: aim SaO2 94-98%</div><div class=\"answer-line\">PEEP 5 cmH2O  PS 10 cmH2O : May develop parenchymal damage giving ARDS picture</div><div class=\"answer-line\">TV 6ml/kg: Permissive hypercapnoea</div><div class=\"answer-line\">Plateau pressures &lt;30cmH20: minimise baroutrauma</div><div class=\"answer-line\"><strong>Ref: </strong></div><div class=\"answer-line\"><strong>burns</strong><strong>   </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"You have been tasked to retrieve a 42-year-old female from a rural base hospital to a tertiary referral centre 400km away. The estimated flight time is 75 minutes. She was brought into ED after a polypharmacy overdose 90 minutes ago and is presumed to have ingested:\n• Paracetamol 15 tablets x 500mg (7.5 grams)\n• Olanzapine 25 tablets x 10mg (250mg)\n• Diazepam 5 tablets x 5mg (25)\nHer observations are:\n\nSaO2\n92%RA\n\nBP\n100/60 mmHg Pulse 110 bpm\n\nRR\n22breaths/min\n\nGCS\nE2V4M4","parts":[{"id":"a","label":"Part A","prompt":". State how you would manage this patient to enable safe transportation. For each decision provide a justification. (8 marks) Decision Justification"},{"id":"b","label":"Part B","prompt":". Complete the following table for the dose-related clinical effects that you would anticipate from an Olanzapine over"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Decision</td><td>Justification</td></tr><tr><td>Intubate and ventilate - drugs/doses required - Any</td><td>Airway protection due to predicted sedation</td></tr><tr><td>reasonable choice<strong> </strong></td><td>Agitated patient is a safety risk on a flight</td></tr><tr><td>Ongoing sedation - Any reasonable choice</td><td>Minimize complications during transfer</td></tr><tr><td>Ongoing Relaxation - Vecuronium 10 mg IV PRN</td><td>Minimize complications during transfer e.g</td></tr><tr><td>tube dislodgement/chewing on tube</td><td></td></tr><tr><td>IV fluids<strong> </strong></td><td>Maintenance + bolus for predicted</td></tr><tr><td>hypotension</td><td></td></tr><tr><td>Cardiac monitoring with defibrillation pads on<strong> </strong></td><td>Possibility of arrhythmia/QT prolongation</td></tr><tr><td>2x IV access with long extensions (more than 2</td><td>Easier drug administration</td></tr><tr><td>preferred)<strong> </strong></td><td></td></tr><tr><td>Vasopressors prepared and ready to give -</td><td>Predicted hypotension</td></tr><tr><td>drug/dose required - Any reasonable choice<strong> </strong></td><td></td></tr><tr><td>NG tube insertion</td><td>Decompress stomach</td></tr><tr><td>IDC insertion</td><td>Patient care on long flight, decompress Pati</td></tr><tr><td>bladder</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">The Emergency Medicine Manual - Dunn et. al.</div><div class=\"answer-line\">The Toxicology Handbook - 3rd edition</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 62-year-old man is brought in by ambulance to your tertiary hospital after a low-speed dirt bike accident. He was riding up a hill, hit a mound, and fell backwards onto his left chest and shoulder. He did not lose consciousness and mobilised at the scene. On assessment, he is alert and talking. His respiratory rate is 20 breaths/minute with shallow respirations, his SaO2 is 92% on room air; BP is 130/80, his heart rate is 95 bpm, his GCS is 15 and his temperature is 36.2 degrees Celsius. His abdomen is soft and non-tender. A chest x-ray is performed and is shown in the Props Booklet (Figure 9)","parts":[{"id":"a","label":"Part A","prompt":"List three positive and two negative findings on this Chest x-ray.(5 marks)"},{"id":"b","label":"Part B","prompt":"List and justify two further investigations you would request for this patient. (4 marks) Investigation Justification You decide he needs admission for analgesia and observation, however he refuses to stay."},{"id":"c","label":"Part C","prompt":"List the medico-legal requirements necessary for him to be declared competent to make this decision (4 marks) THE END TIME FOR LUNCH..............."}],"propPages":["asset:img8c1264a69ff919e9d9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Multiple left-sided rib fractures including displaced fractures of 5th and 6th Ribs</div><div class=\"answer-line\">posterolaterally.</div><div class=\"answer-line\">Comminuted # of the mid-third of the left clavicle with 13mm craniocaudal offset</div><div class=\"answer-line\">Patchy airspace opacification at the left lower lobe – likely contusion.</div><div class=\"answer-line\">No significant haemo- or pneumothorax</div><div class=\"answer-line\">No subcutaneous emphysema</div><div class=\"answer-line\">Cardiac contour appears normal</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Further define injuries seen and evaluate for subtle PTx, </strong></td></tr><tr><td colspan=\"2\"><strong>HTx, mediastinal haematoma, radiological flail. </strong></td></tr><tr><td>ECG</td><td>Cardiac contusion (dysrhythmia or ST segment changes)</td></tr><tr><td>FBE, UEG, LFT, lipase, G&amp;H, coags</td><td>Evaluate Hb (and baseline), G&amp;H in case of transfusion</td></tr><tr><td>Blood gas</td><td>Early signs of hypoventilation secondary to rib # pain</td></tr><tr><td colspan=\"2\">(raised pCO2).</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cognitive capacity: understand the condition, treatment options, potential outcomes, likelihood</div><div class=\"answer-line\">Able to accept/retain/paraphrase info, explain consequences, reasons for their decision</div><div class=\"answer-line\">Mental state: not altered by medical conditions+ Not impaired by alcohol/drugs + MMSE&gt;20</div><div class=\"answer-line\">Age : adult – given in stem</div><div class=\"answer-line\">Ref: Dunn (admin)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
